function graphic(kind, label = '', large = false) {
  if (kind === 'gutenberg-logo') return `<a class="gutenberg-logo" href="https://www.gutenberg.org/" target="_blank" rel="noopener"><img src="/assets/chapitre1/project-gutenberg-logo.jpg" alt="Logo officiel de Project Gutenberg, avec une presse à imprimer." width="576" height="360"></a>`;
  if (kind === 'tei-example') return `<a class="tei-example" href="/assets/chapitre1/tei-persname.svg" target="_blank" rel="noopener"><img src="/assets/chapitre1/tei-persname.svg" alt="Exemple réel d’encodage TEI : persName contient les prénoms Edward et George dans des balises forename et le nom Bulwer-Lytton dans une balise surname." width="760" height="440"></a>`;
  if (kind === 'dvr1000') return `<div class="dvr-crop" role="img" aria-label="Photographie du magnétoscope numérique Sony DVR-1000, détail d’une image d’archives de Sony."><img src="/assets/chapitre1/sony-dvr1000-source.png" alt="" width="1280" height="660"></div>`;
  if (kind === 'text-history') return `<div class="text-history-photos"><figure><a href="/assets/chapitre1/ibm-mtst.jpg" target="_blank" rel="noopener"><img src="/assets/chapitre1/ibm-mtst.jpg" alt="Photographie d’une opératrice utilisant le MT/ST d’IBM : machine à écrire et unité de stockage sur bande, sans écran." width="1200" height="951"></a><figcaption>IBM MT/ST · machine à écrire et bande magnétique · <a href="https://commons.wikimedia.org/wiki/File:IBM_Magnetic_Tape-Selectric_Typewriter_in_use.jpg" target="_blank" rel="noopener">Norsk Teknisk Museum</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a></figcaption></figure><figure><a href="/assets/chapitre1/nls-1969.jpg" target="_blank" rel="noopener"><img src="/assets/chapitre1/nls-1969.jpg" alt="Photographie de 1969 : Douglas Engelbart et ses collègues à SRI, devant les écrans du système NLS en usage." width="660" height="439"></a><figcaption>NLS à SRI, 1969 · <a href="https://commons.wikimedia.org/wiki/File:Augmentation_Research_Center_Wired_Article.jpg" target="_blank" rel="noopener">SRI International / Wikimedia Commons</a></figcaption></figure></div>`;
  if (kind === 'univac') return `<img class="univac-photo" src="/assets/chapitre1/univac-1951.jpg" alt="Photographie de l’UNIVAC I : console de commande, deux opérateurs et rangée de lecteurs de bandes UNISERVO." width="3748" height="2728">`;
  if (kind === 'portrait') return `<div class="portrait-object ${large ? 'large' : ''}"><img src="/assets/kirsch-1957.webp" alt="Portrait en niveaux de gris de Walden Kirsch, numérisé en 1957" width="480" height="480"><span>176 × 176 pixels · 1957</span></div>`;
  const common = `viewBox="0 0 480 290" role="img" aria-label="${esc(label || 'Schéma pédagogique, représentation contemporaine')}"`;
  if (kind === 'punch') return `<svg ${common}><rect x="20" y="35" width="440" height="215" rx="5" fill="#dbc5a1"/><path d="M20 56L42 35" stroke="#101c20" stroke-width="15"/><text x="44" y="67" fill="#453f35" font-size="12" font-family="monospace">H U M A N I T É S  /  N U M É R I Q U E S</text>${Array.from({length: 29}, (_, c) => Array.from({length: 7}, (_, r) => `<rect x="${46+c*13.5}" y="${92+r*18}" width="5" height="10" fill="${((c*7+r*11+c*r)%9)<3?'#263239':'#b5a585'}" opacity="${((c*7+r*11+c*r)%9)<3?1:.3}"/>`).join('')).join('')}<path d="M40 225H440" stroke="#9b8c70"/><text x="42" y="241" fill="#453f35" font-size="9" font-family="monospace">ENCODER · TRIER · RETROUVER</text></svg>`;
  if (kind === 'wave') return `<svg ${common}><path d="M25 145H455M50 35V255" stroke="#61767a" stroke-width="1"/><path d="${Array.from({length:400},(_,i)=>`${i?'L':'M'}${40+i},${145+Math.sin(i*.045)*75}`).join(' ')}" fill="none" stroke="#e6ae80" stroke-width="2"/>${Array.from({length:28},(_,i)=>`<circle cx="${40+i*14}" cy="${145+Math.sin(i*14*.045)*75}" r="4" fill="#86b7ac"/>`).join('')}<text x="45" y="280" fill="#a8bab8" font-size="12" font-family="monospace">UN SIGNAL → DES MESURES → DES VALEURS</text></svg>`;
  if (kind === 'reel') return `<svg ${common}><rect x="40" y="30" width="400" height="230" rx="8" fill="#25343a" stroke="#637477"/>${[148,332].map(x=>`<circle cx="${x}" cy="137" r="79" fill="#162327" stroke="#acb6ad" stroke-width="7"/><circle cx="${x}" cy="137" r="22" fill="#9faea7"/>${[0,120,240].map(a=>`<path d="M${x} 137l0-61" transform="rotate(${a} ${x} 137)" stroke="#9faea7" stroke-width="14"/>`).join('')}`).join('')}<path d="M150 215H330" stroke="#e6ae80" stroke-width="7"/><text x="120" y="251" fill="#c7d1c8" font-size="11" font-family="monospace">CONSERVER AUSSI LE MOYEN DE LIRE</text></svg>`;
  if (kind === 'film') return `<svg ${common}><rect x="20" y="55" width="440" height="180" fill="#070d10"/>${[40,182,324].map((x,i)=>`<rect x="${x}" y="80" width="116" height="127" fill="#375053"/><circle cx="${x+35+i*19}" cy="130" r="22" fill="#e6ae80"/><text x="${x+8}" y="199" fill="#e9e9d9" font-size="10" font-family="monospace">00:00:0${i+1}</text>`).join('')}${Array.from({length:24},(_,i)=>`<path d="M${31+i*18} 63v8m0 148v8" stroke="#93a19d" stroke-width="8"/>`).join('')}</svg>`;
  if (kind === 'text' || kind === 'book' || kind === 'code') return `<svg ${common}><rect x="75" y="20" width="330" height="250" rx="2" fill="#e9dfcd"/><text x="100" y="60" font-size="13" font-family="monospace" fill="#725c4b">${kind==='code'?'&lt;document&gt;':'TRACES / FRAGMENT 01'}</text>${Array.from({length:7},(_,i)=>`<rect x="100" y="${85+i*22}" width="${[250,212,243,175,248,230,156][i]}" height="5" fill="${i===3?'#b7714b':'#82908a'}"/>`).join('')}<rect x="155" y="145" width="90" height="17" fill="#b7714b" opacity=".25"/><text x="100" y="255" font-size="11" font-family="monospace" fill="#725c4b">${kind==='code'?'&lt;/document&gt;':'SOURCE → TEXTE → INDEX'}</text></svg>`;
  const points = [[80,80],[200,40],[340,65],[410,160],[290,230],[130,225],[210,140],[70,170],[320,135]];
  return `<svg ${common}>${[[0,1],[0,6],[0,7],[1,2],[1,6],[2,8],[2,3],[3,8],[3,4],[4,5],[4,6],[5,6],[5,7],[6,8],[7,6]].map(([a,b])=>`<path d="M${points[a]}L${points[b]}" stroke="#678b87" stroke-width="1.4"/>`).join('')}${points.map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="${i===6?22:7+i%4*2}" fill="${i===6?'#e6ae80':'#86b7ac'}"/><circle cx="${x}" cy="${y}" r="${i===6?34:18}" fill="none" stroke="#86b7ac" opacity=".15"/>`).join('')}</svg>`;
}

