function layerDemo() {
  const layers = [
    {
      name: 'La source', title: '', label: 'Archive réelle · Z14-003-00770 · SPAA / Ana’ite',
      content: `<div class="postcard-faces">
        <figure><a href="/assets/chapitre1/Z14-003-00770-v.jpg" target="_blank" rel="noopener"><img src="/assets/chapitre1/Z14-003-00770-v.jpg" alt="Recto illustré : coucher de soleil sur Moorea vu depuis Tahiti, édition G. Spitz." width="1694" height="1094"></a><figcaption>Recto · image et légende imprimée</figcaption></figure>
        <figure><a href="/assets/chapitre1/Z14-003-00770-r.jpg" target="_blank" rel="noopener"><img src="/assets/chapitre1/Z14-003-00770-r.jpg" alt="Verso : message manuscrit daté de Papeete le 19 janvier 1929, adresse de J. Vidal à Marseille, timbre de 40 centimes oblitéré et tampon du fonds Gutzwiller." width="1779" height="1172"></a><figcaption>Verso · message, adresse et timbre. Cliquez sur une face pour l’agrandir.</figcaption></figure>
      </div>`,
      note: 'Que voit-on ici ?'
    },
    {
      name: 'La donnée', title: '', label: 'Transcription manuelle partielle · réalisée pour le cours',
      content: `<div class="postcard-transcription"><h4>Légende du recto · extrait</h4><blockquote class="source-body">98. - TAHITI. - Coucher de Soleil sur Moorea<br>Sunset on Moorea</blockquote><h4>Verso · date et adresse</h4><blockquote class="source-body">Papeete le 19/1/29<br><br>Monsieur J. Vidal<br>14 Rue d’Alger<br>Marseille<br>France</blockquote><dl class="metadata"><dt>Date normalisée</dt><dd><code>1929-01-19</code></dd><dt>Valeur du timbre</dt><dd>40 centimes</dd></dl></div>`,
      note: 'Quels sont tous les choix faits lors de la transcription des données ?'
    },
    {
      name: 'La métadonnée', title: '', label: 'Notice pédagogique · appuyée sur la notice Ana’ite',
      content: `<dl class="metadata"><dt>Identifiant de l’objet</dt><dd>Z14-003-00770</dd><dt>Type</dt><dd>Carte postale ; deux fichiers pour un même objet</dd><dt>Titre</dt><dd>98. - Tahiti. - Coucher de Soleil sur Moorea</dd><dt>Éditeur</dt><dd>Edition G. Spitz</dd><dt>Photographe</dt><dd>Non identifié dans la notice</dd><dt>Édition estimée</dt><dd>Vers 1914–1920, selon Ana’ite (analyse du papier)</dd><dt>Correspondance</dt><dd>19 janvier 1929 ; Papeete</dd><dt>Destinataire</dt><dd>J. Vidal ; Marseille, France</dd><dt>Conservation</dt><dd>SPAA ; fonds GUTZWILLER (Fi14)</dd><dt>Numérisation</dt><dd>2017, selon la notice</dd><dt>Droits de diffusion</dt><dd>CC BY-NC-SA ; version non précisée par Ana’ite</dd></dl>`,
      note: 'Peut-on partager ce document ? Peut-on le modifier puis le partager ? Quelles métadonnées pourrait-on ajouter ?',
      resource: '<div class="layer-resource"><span class="mini-label">CREATIVE COMMONS</span><p><a href="https://creativecommons.org/cc-licenses/" target="_blank" rel="noopener">Comprendre les différentes licences Creative Commons ↗</a></p></div>'
    },
    {
      name: 'L’interprétation', title: '', label: 'QUE PEUT-ON APPRENDRE DE CETTE IMAGE ?',
      content: `<p>L’interprétation ouvre le champ des hypothèses. Le même document peut appuyer ou attaquer une hypothèse. Ici l’hypothèse pourrait être technologique, géographique, sociale, politique, économique...</p><p>Aucun choix de document, que ce soit dans un musée ou un manuel scolaire, n’est anodin. La source, la donnée, et la métadonnée contribuent à favoriser des interprétations et en éviter d’autres.</p>`,
      note: 'Quels exemples d’hypothèses cette image pourrait contribuer à renforcer ou attaquer ?'
    }
  ];
  const l = layers[state.layer];
  return `<div class="layer-demo">
    <div class="tab-bar" role="group" aria-label="Représentations du document">${layers.map((l,i)=>`<button data-layer="${i}" aria-pressed="${i===state.layer}"><span>0${i+1}</span>${l.name}</button>`).join('')}</div>
    <div class="layer-content" aria-live="polite">
      <div>${stamp(l.label)}${l.title ? `<h3>${l.title}</h3>` : ''}${l.content}</div>
      <aside><span class="mini-label">Question</span><p>${l.note}</p>${l.resource || ''}</aside>
    </div>
    <p class="postcard-credit">SPAA, fonds GUTZWILLER (Fi14), Z14-003-00770 · Numérisation : 2017 · Diffusion : CC BY-NC-SA (version non précisée). <a href="https://anaite.upf.pf/s/anaite/item/49989" target="_blank" rel="noopener">Notice Ana’ite / UPF ↗</a> · <a href="/assets/chapitre1/NOTICE.txt">Crédit et conditions de réutilisation</a></p>
  </div>`;
}
function timelineDemo() {
  const t = timeline[state.timeline];
  return `<div class="timeline-demo"><div class="timeline-nav" role="group" aria-label="Repères historiques">${timeline.map((t,i)=>`<button data-era="${i}" aria-pressed="${i===state.timeline}"><span>${t.year}</span><small>${t.family}</small></button>`).join('')}</div><div class="timeline-panel" aria-live="polite"><div class="timeline-object">${graphic(t.visual,t.object)}<span class="object-caption">${t.object}${t.visual==='portrait'?' · R. Kirsch / NIST':t.visual==='univac'?' · U.S. Census Bureau · 1951 · domaine public':t.visual==='dvr1000'?' · © Sony · détail':t.visual==='text-history'?' · photographies d’archives':t.visual==='gutenberg-logo'?' · logo officiel':t.visual==='tei-example'?' · exemple d’encodage TEI':' · schéma pédagogique'}${t.visual==='dvr1000'?' · <a href="https://note.com/sonycorporation/n/n30bbfd5421fe" target="_blank" rel="noopener">Source Sony ↗</a>':''}${t.visual==='tei-example'?' · <a href="https://tei-c.org/release/doc/tei-p5-doc/en/html/ref-persName.html" target="_blank" rel="noopener">Extrait de l’exemple officiel ↗</a>':''}</span></div><div class="timeline-copy"><span class="eyebrow">${t.year} / ${t.family}</span><h3>${t.title}</h3><p>${t.text}</p>${t.context ? `<div class="timeline-context"><h4>${t.contextTitle}</h4>${t.context.map(text=>`<p>${text}</p>`).join('')}<div class="source-links">${sourceLink(t.contextSource)}</div></div>` : ''}<div class="source-links">${sourceLink(t.source)}${t.extra ? sourceLink(t.extra) : ''}</div></div></div><div class="timeline-footer"><button class="text-link" data-action="era-prev" ${state.timeline===0?'disabled':''}>← Repère précédent</button><span class="mono">${String(state.timeline+1).padStart(2,'0')} / ${timeline.length}</span><button class="text-link" data-action="era-next" ${state.timeline===timeline.length-1?'disabled':''}>Repère suivant →</button></div></div>`;
}

function chapter(id) {
  const c = chapters.find(c=>c.id===id);
  if (!c) return notFound();
  if (id===7) return shell(`<main id="main" class="course-layout" tabindex="-1">${sidebar(7)}${chapterSeven()}</main>`,'chapter');
  if (id===9) return shell(`<main id="main" class="course-layout" tabindex="-1">${sidebar(9)}${chapterNine()}</main>`,'chapter');
  if (id===8) return shell(`<main id="main" class="course-layout" tabindex="-1">${sidebar(8)}${chapterEight()}</main>`,'chapter');
  if (id===6) return shell(`<main id="main" class="course-layout" tabindex="-1">${sidebar(6)}${chapterSix()}</main>`,'chapter');
  if (id===5) return shell(`<main id="main" class="course-layout" tabindex="-1">${sidebar(5)}${chapterFive()}</main>`,'chapter');
  if (id===4) return shell(`<main id="main" class="course-layout" tabindex="-1">${sidebar(4)}${chapterFour()}</main>`,'chapter');
  if (id===3) return shell(`<main id="main" class="course-layout" tabindex="-1">${sidebar(3)}${chapterThree()}</main>`,'chapter');
  if (id===2) return shell(`<main id="main" class="course-layout" tabindex="-1">${sidebar(2)}${chapterTwo()}</main>`,'chapter');
  if (id!==1) return shell(`<main id="main" class="course-layout" tabindex="-1">${sidebar(id)}<article class="course-article"><div class="chapter-hero">${stamp(`Chapitre ${String(id).padStart(2,'0')} / ${c.tag}`)}<h1>${c.title}</h1><p class="lead">${c.desc}</p><span class="badge">Contenu en préparation</span></div><section class="lesson-section"><h2>Ce que nous explorerons</h2><ul class="objectives">${c.objectives.map(x=>`<li>${x}</li>`).join('')}</ul><p>Cette page présente la place du chapitre dans le parcours. Les ressources de ce chapitre seront disponibles ultérieurement.</p><div class="actions">${button('Revenir au chapitre 1','#/chapitre/1')}${button('Voir le programme','#/accueil',true)}</div></section></article></main>`,'chapter');
  return shell(`<main id="main" class="course-layout" tabindex="-1">${sidebar()}<article class="course-article"><div class="chapter-hero" id="ouverture">${stamp('Chapitre 01 / Fondations')}<h1>Des humanités<br>aux humanités<br><em>numériques.</em></h1><p class="lead">Comprendre ce que l’on transforme quand on transforme une trace humaine en donnée.</p><div class="chapter-hero-bottom">${button('Mode projection','#/projection/0',true)}</div></div><nav class="on-this-page" aria-label="Dans ce chapitre"><span>Dans cette salle</span>${sections.slice(1).map(([id,name])=>`<a href="#${id}" data-scroll="${id}">${name}</a>`).join('')}</nav><section class="lesson-section" id="humanites"><div class="section-kicker">01 / TROIS NOTIONS</div><h2>Les humanités, le numérique,<br>et leur rencontre.</h2><div class="definition-grid"><div><span class="definition-no">01</span><h3>Les humanités</h3><p>Étudier et interpréter les textes, les langues, les arts, les histoires et les expériences humaines. Leurs frontières varient ; elles dialoguent notamment avec l’anthropologie, la sociologie et la géographie.</p></div><div><span class="definition-no">02</span><h3>Le numérique</h3><p>Représenter des informations à l’aide de signes discrets, puis les stocker, les transmettre et les transformer par calcul. Ce fonctionnement repose sur des conventions, des appareils et du travail humain.</p></div><div><span class="definition-no">03</span><h3>Les humanités numériques</h3><p>Associer des questions des humanités à des méthodes numériques, tout en examinant comment ces méthodes, leurs données et leurs infrastructures influencent les savoirs produits.</p></div></div><div class="callout"><span class="callout-label">Une distinction utile</span><p><strong>Numériser</strong>, c’est produire une représentation numérique. <strong>Faire une enquête en humanités numériques</strong>, c’est aussi poser une question, construire un corpus, interpréter les résultats et rendre les choix discutables. La numérisation peut être une étape de cette enquête.</p></div><p>Le numérique peut également devenir l’objet de l’enquête : étudier une communauté en ligne, l’histoire d’un logiciel, les effets d’un moteur de recherche ou les conditions de travail derrière une base de données.</p></section><section class="lesson-section" id="representer"><div class="section-kicker">02 / LA CHAÎNE DOCUMENTAIRE</div><h2>Une trace. Quatre façons<br>de la regarder.</h2><div id="layer-container">${layerDemo()}</div><p class="lesson-takeaway">La donnée est un construit. Une métadonnée est une donnée à propos d’une autre donnée.</p></section><section class="lesson-section" id="histoire"><div class="section-kicker">03 / LA GALERIE HISTORIQUE</div><h2>Le numérique a plus d’un siècle.</h2><div id="timeline-container">${timelineDemo()}</div><details><summary>Trois précautions pour lire cette histoire</summary><ul><li><strong>Le numérique ne commence pas avec Internet.</strong> Le codage discret et le traitement mécanisé lui sont antérieurs.</li><li><strong>La technique ne fait pas tout.</strong> Saisie, annotation, traduction, maintenance et sélection mobilisent des personnes, souvent peu visibles dans les récits d’innovation.</li><li><strong>Un repère n’est pas une origine unique.</strong> Les inventions et les pratiques se développent dans plusieurs contextes. Cette sélection reste partielle et située.</li></ul></details></section><section class="lesson-section" id="experiences"><div class="section-kicker">04 / LE LABORATOIRE</div><h2>Toucher du doigt<br>une représentation.</h2><p>Modifiez un paramètre et formulez votre prédiction avant d’observer le résultat. Chaque expérience met en évidence une convention ou une perte d’information.</p><div id="labs-container">${labs()}</div></section><section class="lesson-section" id="regard"><div class="section-kicker">05 / LE REGARD CRITIQUE</div><h2>Quatre questions<br>à garder avec soi.</h2><ol class="critical-list"><li><span>D’où vient la source ?</span><p>Identifiez qui a collecté la source, dans quelle situation et avec quelles informations manquantes. Un fichier trouvé en ligne n’explique pas sa propre histoire.</p></li><li><span>Qui décide de son usage ?</span><p>Identifiez les personnes et les communautés concernées ; examinez les accords de collecte et les conditions d’accès. Une possibilité technique de diffusion ne suffit pas à décider.</p></li><li><span>Qu’a-t-on transformé ?</span><p>Documentez les corrections, les recadrages, les traductions et les traitements automatiques. Préservez la possibilité de revenir à la source.</p></li><li><span>Comment pourra-t-on encore la lire ?</span><p>Conservez les fichiers dans des formats réutilisables, avec leur documentation. Prévoyez les sauvegardes et la transmission des responsabilités.</p></li></ol><div class="callout"><span class="callout-label">Un point d’appui en contexte océanien</span><p>Les principes CARE invitent à considérer le bénéfice collectif, l’autorité de contrôle, la responsabilité et l’éthique dans la gouvernance des données autochtones. Ils complètent les questions techniques de partage. ${sourceLink('care')}</p></div><details><summary>Discussion : davantage de données, davantage de connaissances ?</summary><p>Un grand corpus peut rendre des régularités visibles tout en amplifiant des déséquilibres de collecte. Interrogez-vous : qui parle, dans quelle langue et dans quel genre de document ? Qui est absent ? Une visualisation est le début d’une interprétation à vérifier.</p></details></section><section class="lesson-section chapter-end" id="suite"><div class="section-kicker">À VOUS DE JOUER</div><h2>Passer de l’observation<br>à une décision documentée.</h2><p>Le cours s’arrête ici ; l’atelier commence. Enquêtez sur la photographie de l’atelier, remplissez le tableau et proposez un premier usage documenté. Vous pourrez ensuite reprendre les notions avec les questions de révision.</p><div class="actions">${button('Commencer l’atelier','#/atelier')}${button('Questions de révision','#/quiz',true)}${button('Continuer vers le chapitre 2','#/chapitre/2',true)}</div><div class="completion"><label><input type="checkbox" id="chapter-read" ${visited.includes('chapter1')?'checked':''}> Marquer ce chapitre comme parcouru</label><span>Repère personnel enregistré sur cet appareil.</span></div></section></article></main>`,'chapter');
}

function labs() {
  return `<div class="labs"><div class="tab-bar lab-tabs" role="group" aria-label="Choisir une expérience">${[['texte','01','Texte et bits'],['image','02','Image et pixels'],['son','03','Son et échantillons']].map(([id,n,t])=>`<button data-lab="${id}" aria-pressed="${state.lab===id}"><span>${n}</span>${t}</button>`).join('')}</div><div class="lab-body">${state.lab==='texte'?textLab():state.lab==='image'?imageLab():soundLab()}</div></div>`;
}
function textLab() {
  return `<div class="lab-intro"><span class="badge">EXPÉRIENCE 01</span><h3>Combien pèse un mot ?</h3><p>Saisissez un mot, puis comparez les caractères et les octets nécessaires à son encodage en UTF-8.</p></div><label class="field-label" for="encode-input">Votre texte <small>Quelques signes suffisent pour expérimenter</small></label><input id="encode-input" class="text-input" maxlength="96" value="mémoire" autocomplete="off" spellcheck="false"><div id="encoding-output" aria-live="polite"></div><div class="lab-explanation"><b>Essayez « e », « é », puis « 🌊 ».</b><p>Un caractère peut nécessiter plusieurs octets. Le ruban ci-dessus représente les bits de l’UTF-8 moderne : c’est une analogie visuelle avec la perforation, pas une reconstitution du code de Hollerith ou de Baudot.</p></div><details><summary>Pourquoi 8 bits dans un octet ?</summary><p>Un bit prend deux valeurs. Huit bits permettent 2⁸ = 256 combinaisons. UTF-8 combine un à quatre octets par point de code Unicode ; un caractère visible peut lui-même réunir plusieurs points de code (accent combiné, certains emoji).</p></details>`;
}
function imageLab() {
  return `<div class="lab-intro"><span class="badge">EXPÉRIENCE 02</span><h3>Résolution et profondeur.</h3><p>Faites varier la résolution et le nombre de niveaux de gris du portrait numérisé par l’équipe de Russell Kirsch en 1957.</p></div><div class="image-experiment"><div class="canvas-frame"><canvas id="pixel-canvas" width="352" height="352" role="img" aria-label="Portrait de Walden Kirsch avec résolution et niveaux de gris réglables"></canvas><span id="image-label" class="mono"></span></div><div class="lab-controls"><label for="resolution">Résolution <output id="resolution-value">32 × 32 pixels</output></label><input type="range" id="resolution" min="0" max="5" value="2" step="1"><div class="range-ends"><span>8 × 8</span><span>176 × 176</span></div><label for="gray-bits">Profondeur des niveaux de gris</label><select id="gray-bits"><option value="1">1 bit · 2 niveaux</option><option value="2">2 bits · 4 niveaux</option><option value="4">4 bits · 16 niveaux</option><option value="8" selected>8 bits · 256 niveaux</option></select><div class="metric"><span id="image-weight">1 024</span><small>octets de pixels bruts</small></div><p class="small">Estimation sans en-tête, métadonnées ni compression : largeur × hauteur × bits par pixel ÷ 8.</p></div></div><div class="lab-explanation"><b>Résolution et précision ne sont pas la même chose.</b><p>La résolution détermine la grille spatiale. La quantification détermine les niveaux possibles pour chaque pixel. Remonter les paramètres révèle à nouveau la source chargée : cela ne restaure pas une information perdue dans un fichier déjà dégradé.</p></div><p class="source-note">Source : R. Kirsch / NIST, 1957. Démonstration contemporaine de rééchantillonnage, à partir de la reproduction publiée par le NIST. ${sourceLink('kirsch')}</p>`;
}
function soundLab() {
  return `<div class="lab-intro"><span class="badge">EXPÉRIENCE 03</span><h3>Échantillonner, c’est choisir quand mesurer.</h3><p>Écoutez « Tahiti que tu es belle », puis réduisez la fréquence d’échantillonnage. La courbe représente les valeurs du fichier original ; les points indiquent les mesures conservées à la fréquence choisie.</p></div><p class="source-note">Fichier du cours : <a href="${soundFile}" download>tahiti_que_tu_es_belle.wav ↓</a> · <span id="sound-file-info">Chargement de l’enregistrement…</span></p><canvas id="wave-canvas" width="900" height="250" role="img" aria-label="Valeurs du fichier audio original et points conservés après sous-échantillonnage, sur une fenêtre de 20 millisecondes."></canvas><div class="sound-controls"><div><label for="sound-position">Position de la fenêtre <output id="sound-position-value">2,00 s</output></label><input type="range" min="0" max="14.63" step="0.01" value="2" id="sound-position"><p class="small">Zoom sur 20 ms de l’enregistrement. La position change la vue ; l’écoute porte sur le fichier entier.</p></div><div><label for="sample-rate">Fréquence d’échantillonnage</label><select id="sample-rate"><option value="800">800 échantillons/s</option><option value="1600">1 600 échantillons/s</option><option value="4000" selected>4 000 échantillons/s</option><option value="8000">8 000 échantillons/s</option><option value="16000">16 000 échantillons/s</option><option value="48000">48 000 échantillons/s · original</option></select></div></div><div class="audio-buttons"><button class="button secondary" data-action="play-original" disabled>▶ Écouter l’original</button><button class="button secondary" data-action="play-sampled" disabled>▶ Écouter après échantillonnage</button><button class="text-link" data-action="stop-audio">Arrêter</button></div><p id="sound-playback-status" class="small" role="status">Chargement de l’audio…</p><div id="audio-feedback" class="callout" aria-live="polite"></div><div class="lab-explanation"><b>Moins de mesures, une autre restitution.</b><p>Le fichier est déjà numérique : nous réduisons ici sa fréquence d’échantillonnage. Pour l’écoute, chaque mesure conservée est maintenue jusqu’à la suivante ; la durée et la vitesse de lecture restent identiques. Le filtre anti-repliement est volontairement absent pour rendre les déformations audibles. Une conversion destinée à conserver fidèlement le son utiliserait un tel filtre avant la réduction.</p></div>`;
}

function labPage() {
  return shell(`<main id="main" class="standalone" tabindex="-1"><div class="page-heading">${stamp('Le laboratoire / Chapitre 01')}<h1>Comprendre<br><em>par l’expérience.</em></h1><p>Trois transformations à observer. Une question commune : que garde-t-on, que change-t-on, que perd-on ?</p></div><div id="labs-container">${labs()}</div><div class="actions">${button('Revenir au chapitre 1','#/chapitre/1',true)}${button('Passer à l’atelier 1','#/atelier')}${button('Laboratoire du chapitre 2','#/laboratoire/2',true)}</div></main>`,'lab');
}

function field(id,label,placeholder,rows=3) { return `<label class="field-label" for="${id}">${label}</label><textarea id="${id}" data-draft="${id}" rows="${rows}" placeholder="${placeholder}">${esc(draft[id]||'')}</textarea>`; }
function workshop() {
  const photo = documents[0];
  return shell(`<main id="main" class="standalone workshop" tabindex="-1">
    <div class="page-heading">${stamp('Atelier 01 / En binômes')}<h1>Enquêter sur une image.<br><em>Construire une notice.</em></h1><p>Une seule pièce documentaire : <strong>${photo.file}</strong>. Votre travail consiste à enquêter sur cette photographie et à remplir le tableau ci-dessous en distinguant observations, métadonnées, informations vérifiées et hypothèses.</p><div class="actions"><a class="button" href="${photo.url}" download="${photo.file}">Télécharger le JPEG original ↓</a><a class="button secondary" href="/assets/atelier-chapitre-1.zip" download>Télécharger le dossier de travail · ZIP ↓</a><button class="button secondary" data-action="print">Imprimer les consignes</button></div></div>
    <section aria-labelledby="workshop-photo-title"><div class="section-heading"><div>${stamp('01 / La pièce documentaire')}<h2 id="workshop-photo-title">Observer, puis enquêter.</h2></div></div>
      <figure class="workshop-photo"><a href="${photo.url}" target="_blank" rel="noopener"><img src="${photo.url}" width="4000" height="3000" alt="Deux personnes assises sur une pente herbeuse devant une baie et des crêtes montagneuses ; l’une tient un microphone. Une mention figure en bas à droite."></a><figcaption>La mention de la source et de la license sont omises volontairement.</figcaption></figure>
    </section>
    <div class="callout"><span class="callout-label">Commencez par télécharger l’original</span><p>Utilisez le bouton « Télécharger le JPEG original » : il fournit le fichier déposé pour l’atelier, avec ses métadonnées intégrées, sans réencodage. Conservez-le et travaillez à partir d’une copie. Une capture d’écran ne contient pas ces métadonnées.</p></div>
    <ol class="workshop-instructions"><li><strong>Observer l’image.</strong> Décrivez la scène et relevez la mention en bas à droite, sans déduire ce que vous ne pouvez pas encore établir.</li><li><strong>Examiner le fichier téléchargé.</strong> Commencez avec les outils de votre ordinateur, puis utilisez ExifTool pour lire les métadonnées EXIF, IPTC et XMP. Dépliez le guide correspondant à votre système.<p class="metadata-downloads"><a href="https://exiftool.org/" target="_blank" rel="noopener">Télécharger ExifTool · site officiel ↗</a> · <a href="https://exiftool.org/install.html" target="_blank" rel="noopener">Notice officielle d’installation ↗</a></p>${metadataGuides.map(guide=>`<details class="metadata-guide"><summary>${guide.title} · pas à pas</summary><ol>${guide.steps.map(step=>`<li><p>${esc(step.text)}</p>${step.command?`<pre><code>${esc(step.command)}</code></pre>`:''}</li>`).join('')}</ol></details>`).join('')}<p class="small">Dans le relevé, <code>-G1</code> indique le groupe de chaque champ, <code>-a</code> conserve les champs de même nom présents à plusieurs endroits et <code>-s</code> affiche leurs noms techniques. Si un lecteur n’affiche pas un champ, cela ne prouve pas son absence. Reportez les noms et valeurs utiles dans le tableau, avec vos vérifications.</p></li><li><strong>Confronter les indices.</strong> Comparez le nom du fichier, la mention visible et les métadonnées ; cherchez des sources complémentaires pour vérifier vos hypothèses.</li><li><strong>Renseigner le tableau.</strong> Pour chaque affirmation, indiquez son appui : détail de l’image, nom et valeur d’un champ de métadonnées, ou référence externe avec sa date de consultation. Signalez les contradictions et les informations inconnues.</li></ol>
    <section class="workbook"><div class="section-heading"><div>${stamp('02 / Votre tableau d’enquête')}<h2>Documenter vos décisions.</h2></div><p>Le brouillon est conservé dans ce navigateur, sur cet appareil. Exportez-le pour le remettre ou le partager.</p></div>
      <form id="workbook-form"><label class="field-label" for="mission">L’usage envisagé par votre groupe</label><select id="mission" data-draft="mission"><option value="">Choisir une situation professionnelle</option>${['Musée : préparer une exposition','Mairie : concevoir un parcours de mémoire','Documentation : construire un catalogue','Université : constituer un corpus pédagogique'].map(m=>`<option ${draft.mission===m?'selected':''}>${m}</option>`).join('')}</select>${field('question','Votre question et votre public','À quel public vous adressez-vous ? Quelle question votre enquête doit-elle permettre d’explorer ?',2)}
      <table class="investigation-table"><caption>Enquête sur ${photo.file} · justifiez chaque réponse par ses sources.</caption><thead><tr><th scope="col">Rubrique</th><th scope="col">Votre réponse, ses appuis et ses limites</th></tr></thead><tbody>${workshopFields.map(([id,label,prompt])=>`<tr><th scope="row"><label for="${id}">${label}</label><p>${prompt}</p></th><td><textarea id="${id}" data-draft="${id}" rows="5" aria-label="${label}" placeholder="Réponse ; indices ou sources ; limites et vérifications…">${esc(draft[id]||'')}</textarea></td></tr>`).join('')}</tbody></table>
      <p id="save-status" class="small" role="status">Brouillon personnel · aucun envoi à un serveur.</p><div class="actions"><button class="button" type="button" data-action="export-notes">Exporter mon carnet · .md ↓</button><button class="button secondary" type="button" data-action="export-json">Sauvegarder · .json ↓</button><label class="file-label">Reprendre une sauvegarde <input type="file" id="import-notes" accept="application/json,.json"></label></div></form>
    </section><section class="workshop-restatement"><div class="section-heading"><div>${stamp('03 / La restitution')}<h2>Présenter une enquête argumentée.</h2></div><p>Présentez l’image, vos principaux indices, une incertitude importante et la prochaine action proposée. Un autre groupe formule une objection ou une question.</p></div><div class="rubric"><div><b>Décrire</b><p>La notice identifie le fichier et distingue observations, métadonnées et informations inconnues.</p></div><div><b>Justifier</b><p>L’enquête cite des indices précis et les sources consultées ; elle distingue faits et hypothèses.</p></div><div><b>Décider</b><p>L’usage proposé tient compte des conditions de réutilisation et des vérifications encore nécessaires.</p></div></div></section><div class="actions">${button('Questions de révision','#/quiz')}${button('Revenir au cours','#/chapitre/1',true)}</div>
  </main>`,'chapter');
}

function quizPage() {
  return shell(`<main id="main" class="standalone narrow" tabindex="-1">
    <div class="page-heading">${stamp('Chapitre 01 / Questions de révision')}<h1>Cinq questions.<br><em>Un regard plus précis.</em></h1>
      <p>Choisissez une réponse par question et justifiez vos choix. Vous pouvez exporter vos réponses pour les reprendre ou en discuter en groupe.</p>
    </div>
    <form id="quiz-form">${quiz.map((q,i)=>`<fieldset class="quiz-question">
      <legend><span>0${i+1}</span>${q.question}</legend>
      ${q.answers.map((a,j)=>`<label><input type="radio" name="q${i}" value="${j}" required><span>${a}</span></label>`).join('')}
      <label class="field-label" for="reason-${i}">Votre justification</label>
      <textarea id="reason-${i}" name="reason${i}" rows="2" placeholder="Expliquez votre choix en vous appuyant sur le cours."></textarea>
    </fieldset>`).join('')}
      <button class="button" type="submit">Exporter mes réponses · .md ↓</button>
    </form>
    <div class="actions">${button('Revenir au chapitre','#/chapitre/1',true)}${button('Retrouver mon atelier','#/atelier',true)}</div>
  </main>`,'chapter');
}

function glossaryPage() {
  return shell(`<main id="main" class="standalone narrow" tabindex="-1"><div class="page-heading">${stamp('Les mots du cours')}<h1>Un vocabulaire<br><em>pour se comprendre.</em></h1><p>Des définitions de travail, à relier aux exemples et aux questions du cours.</p></div><label class="field-label" for="glossary-search">Rechercher un terme ou une notion</label><input id="glossary-search" class="text-input" type="search" placeholder="Ex. corpus, donnée, échantillonnage…"><p id="glossary-count" class="small" role="status">${glossary.length} notions</p><dl class="glossary-list">${glossary.map(([term,def])=>`<div data-glossary="${esc((term+' '+def).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase())}"><dt>${term}</dt><dd>${def}</dd></div>`).join('')}</dl></main>`,'glossary');
}
function sourcesPage() {
  return shell(`<main id="main" class="standalone" tabindex="-1"><div class="page-heading">${stamp('Sources et crédits')}<h1>Revenir<br><em>aux sources.</em></h1><p>Les références historiques et les ressources citées dans les neuf chapitres. Les dates de consultation propres aux ajouts figurent dans les chapitres et les notices ; les références initiales datent du 6 novembre 2026. Les liens externes nécessitent Internet.</p></div><div class="source-list">${[...sources,...chapter2Sources,...chapter3Sources,...chapter4Sources,...chapter5Sources,...chapter6Sources,...chapter7Sources,...chapter8Sources,...chapter9Sources].map((s,i)=>`<article><span class="mono">${String(i+1).padStart(2,'0')}</span><div><span class="eyebrow">${s.org}</span><h2><a href="${s.url}" target="_blank" rel="noopener">${s.title} ${arrow}</a></h2><p>${s.note}</p></div></article>`).join('')}</div><section class="credits"><h2>Images, schémas et fonds-école</h2><p>Portrait de Walden Kirsch : R. Kirsch / NIST, 1957, reproduction de la page « First Digital Image ». Le simulateur applique un rééchantillonnage et une quantification ; les affichages modifiés sont des démonstrations pédagogiques réalisées le ${course.updated}.</p><p>Image reproduite avec l’autorisation du National Institute of Standards and Technology. Les conditions de réutilisation et la notice complète accompagnent le fichier dans <a href="/assets/NOTICE-NIST.txt">la notice NIST</a>. <a href="https://www.nist.gov/open/license" target="_blank" rel="noopener">Conditions publiées par le NIST ↗</a></p><p>La chaîne documentaire du chapitre 1 utilise la carte postale « Tahiti — Coucher de Soleil sur Moorea », SPAA, fonds GUTZWILLER (Fi14), Z14-003-00770, diffusée par Ana’ite / UPF sous licence CC BY-NC-SA (version non précisée). Les deux numérisations sont reproduites sans modification ; la transcription partielle et les commentaires ont été réalisés pour le cours. <a href="/assets/chapitre1/NOTICE.txt">Crédit et conditions de réutilisation ↗</a> La photographie de l’UNIVAC I est créditée au U.S. Census Bureau, 1951, et diffusée dans le domaine public via <a href="https://commons.wikimedia.org/wiki/File:Univac_I_Census_dedication.jpg" target="_blank" rel="noopener">Wikimedia Commons</a>. <a href="/assets/chapitre1/NOTICE-UNIVAC.txt">Notice de provenance</a>. Le DVR-1000 est illustré par un détail d’une image publiée par Sony dans son article du 6 mai 2022 consacré à son anniversaire (© Sony). Le MT/ST est illustré par une photographie du Norsk Teknisk Museum sous CC BY-SA 4.0 ; NLS par une photographie SRI International de 1969 publiée sur Wikimedia Commons, signalée comme appartenant au domaine public aux États-Unis. Les liens de provenance et de licence accompagnent les photographies dans la galerie ; <a href="/assets/chapitre1/NOTICE-MTST-NLS-DVR.txt">notice complète des trois images</a>. Le logo Project Gutenberg est reproduit depuis le site officiel du projet et renvoie à celui-ci. L’image d’encodage TEI présente un extrait de l’exemple officiel « persName » du TEI Consortium : les prénoms et le nom sont reproduits ; le titre de noblesse et le nom de lieu de l’exemple complet ont été omis pour la lisibilité. La mise en forme est réalisée pour le cours. <a href="/assets/chapitre1/NOTICE-GUTENBERG-TEI.txt">Provenance du logo et de l’exemple</a>. L’expérience sonore du chapitre 1 utilise le fichier fourni pour le cours « tahiti_que_tu_es_belle.wav », mono, PCM 16 bits, 48 kHz. Le fichier original est conservé ; le sous-échantillonnage et sa restitution sont calculés dans le navigateur, sans filtre anti-repliement. <a href="/assets/chapitre1/audio/NOTICE.txt">Provenance et traitement du son</a>. Les autres illustrations sont des schémas originaux du support. L’atelier du chapitre 1 utilise le JPEG original « Takurua_Parent_2025_Rapa_1.jpg », fourni pour le cours : Photo : Takurua Parent / DIG4EL, © 2025, CC BY-NC-ND 4.0. Le fichier est affiché et téléchargeable sans modification, avec ses métadonnées intégrées. Le chapitre 2 et son atelier utilisent « L’origine du kong Hulup », corpus iaai de Pangloss / COCOON : voix de Taï Waheo, recherche et dépôt de Françoise Ozanne-Rivierre, traduction créditée à Wadawa Hnyigootr. © Françoise Ozanne-Rivierre, LACITO. Le son intégral est sous CC BY-NC-ND 2.5 ; les annotations sous CC BY-NC-SA 2.5. Les fichiers originaux sont conservés sans modification ; leur présentation dans le cours est distincte des commentaires pédagogiques. <a href="/assets/chapitre2/pangloss/NOTICE.txt">Provenance et licences du récit en iaai</a>. Les manipulations complémentaires du chapitre 2 utilisent des exemples français fictifs ; leur voix de synthèse Thomas ne constitue pas un témoignage authentique. Le chapitre 3, « Explorer de grands corpus », utilise Marawa en direct pour les démonstrations et l’atelier. Aucun corpus ni vecteur n’est embarqué dans ce chapitre. Les annotations Marawa sont sous CC BY-NC-SA (version non précisée), selon l’indication du responsable du cours ; les droits des documents originaux restent distincts. Le chapitre 4 et son atelier utilisent des archives réelles du SPAA diffusées par Ana’ite / UPF sous CC BY-NC-SA (version non précisée) : cartes postales de Papeete (Z14-003-00846) et Moorea (Z14-003-00770), fonds GUTZWILLER, édition G. Spitz ; pages de Te Vea no Tahiti des 3 et 10 janvier 1856. Les cartes sont reproduites à l’identique, les pages des PDF rendues en JPEG ; les variantes réduite et inclinée sont signalées comme des transformations pédagogiques. Les sorties OCR brutes proviennent de Tesseract avec un modèle français appliqué au tahitien ; elles ne constituent pas des transcriptions vérifiées. Les manifestes IIIF sont créés pour le cours. <a href="/assets/chapitre4/NOTICE.txt">Provenance, transformations et crédits du chapitre 4</a>. Le chapitre 5 utilise « Te Hua Riirii », Coco Hotahota &amp; Temaeva, album Escale A Papeete (1976 selon la notice Internet Archive). Le FLAC, les deux MP3 et les deux captures de spectrogrammes sont fournis par le responsable du cours et copiés sans modification. La notice ne fournit pas de licence de réutilisation ; leur présence ne vaut pas autorisation de publication. <a href="/assets/chapitre5/te-hua-riirii/NOTICE.txt">Provenance, caractéristiques et droits du chapitre 5</a>. Les étudiants recherchent eux-mêmes une autre piste autorisant découpe et diffusion publique pour l’atelier.</p><p>Le chapitre 6 propose une lecture de la notice du film « Si je t’oublie Opunohu », sous CC BY-NC-ND 3.0 France. Aucune copie du film n’est distribuée avec le cours. Les photographies de Cardboard et de HTC Vive, la figure publiée de Glossopticon et le visuel Augment sont crédités et accompagnés de leurs licences ouvertes. <a href="/assets/chapitre6/NOTICE.txt">Provenance des illustrations du chapitre 6</a>.</p><h3>Fonctionnement et données</h3><p>En version locale, les pages du cours et les expériences intégrées sont utilisables sans connexion à Internet. La recherche d’une piste et de ses droits dans l’atelier du chapitre 5 nécessite Internet. Les démonstrations et l’atelier du chapitre 3 se font dans Marawa et nécessitent une connexion ; certaines fonctions demandent un compte. Les brouillons et les repères de progression sont enregistrés uniquement dans le stockage de ce navigateur ; le site n’utilise ni suivi d’audience ni service d’IA distant. Les liens externes ouvrent les sites cités. Le lecteur Internet Archive du chapitre 6 contacte ce service uniquement après activation ; les illustrations et le calculateur restent accessibles sans connexion.</p></section></main>`);
}

