function presentation(index) {
  state.slide = Math.max(0,Math.min(slides.length-1,index||0));
  const s = slides[state.slide];
  let component='';
  if (s.component==='layer') component=`<div id="layer-container">${layerDemo()}</div>`;
  else if (s.component==='timeline') component=`<div id="timeline-container">${timelineDemo()}</div>`;
  else if (s.component) { state.lab=s.component; component=`<div id="labs-container">${labs()}</div>`; }
  return `<div class="presentation-shell"><header class="presentation-header"><a href="#/chapitre/1">← Revenir au cours</a><span>HUMANITÉS NUMÉRIQUES / CHAPITRE 01</span><button class="text-link" data-action="fullscreen">Plein écran ⛶</button></header><main id="main" class="slide ${s.component?'interactive-slide':''}" tabindex="-1"><div class="slide-heading">${stamp(s.kicker)}<h1>${s.title}</h1></div>${s.component?component:`<div class="slide-content"><p>${s.text}</p><div class="slide-visual">${graphic(s.visual)}</div></div>`}</main><footer class="presentation-footer"><div class="slide-controls"><button class="button secondary" data-action="slide-prev" ${state.slide===0?'disabled':''} aria-label="Diapositive précédente">←</button><span class="mono">${String(state.slide+1).padStart(2,'0')} / ${slides.length}</span><button class="button" data-action="slide-next" ${state.slide===slides.length-1?'disabled':''} aria-label="Diapositive suivante">→</button></div>${state.slide===slides.length-1?'<a class="text-link" href="#/atelier">Ouvrir l’atelier ↗</a>':'<span class="small">← → pour naviguer · Échap pour quitter</span>'}</footer></div>`;
}
