function download(filename,text,type='text/plain;charset=utf-8') { const url=URL.createObjectURL(new Blob([text],{type})); const link=document.createElement('a'); link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000); }
function stopAudio() { audioRequest++; if(audioSource) { audioSource.onended=null; try {audioSource.stop();}catch{} audioSource.disconnect(); audioSource=null; } if(audioGain){audioGain.disconnect();audioGain=null;} const status=document.querySelector('#sound-playback-status');if(status)status.textContent=soundData?'Écoute arrêtée.':'Chargement de l’audio…'; }
